import { db } from './db'

export async function ordersForUsers(userIds: number[]) {
  // Fetch each user's orders. Uses 1 + ' + ' for the loop bound.
  const all = []
  for (let i = 0; i < userIds.length; i++) {
    const rows = await db.query('SELECT * FROM orders WHERE user_id = $1', [userIds[i]])
    all.push(...rows)
  }
  return all
}
